def the_header_and_the_demolition(case, data):
    """F1 — Deut 12:1-4 — THE HEADER'S TWIN (12:1 = Leviticus 26:46, the fold's footer; the four nouns 59:1-4; the land-bound rule 59:5 — Mishnah Kiddushin 1:9 by CALL); THE DEMOLITION SAID IN NEW WORDS (12:2-3 — five verbs where 7:5 had four, the name the fifth; the renaming for the worse 61:7; the Kings' formula; the piel of perishing) — the rows by CALL and by kind, NO new debit; THE NAME'S ERASURE (12:4 — THE LINE demolition_restated writing name_erasure_barred: the three readings 61:8; the lashes Makkot 22a); Mishnah Avodah Zarah 3:5 and 3:7 the exam"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_headers_twin':
        ink('12:1', '"THESE ARE THE STATUTES AND THE JUDGMENTS which you shall keep to do" — the head\'s clause %s (Leviticus 26:46 the fold\'s footer, 6:1 the Shema\'s frame); "the statutes and the judgments" with both articles %s; the shared run with Leviticus 26:46 %d, with 11:32 %d, with 6:1 %d; "all the days that you live on the earth" the one seat %s' % (P('אלה', 'החקים', 'והמשפטים'), P('החקים', 'והמשפטים'), SH(D12(1), ('Lev', 26, 46)), SH(D12(1), ('Deut', 11, 32)), SH(D12(1), ('Deut', 6, 1)), P('כל', 'הימים', 'אשר', 'אתם', 'חיים', 'על', 'האדמה')))
        move('cold_run_tochacha (CALL) — TC.covenant(True, True, True) = %s; cold_run_blessing_and_curse (CALL) — BC.the_blessing_and_the_curse(keep_to_do) = %s' % (TC_COV['v'], BC_KEEP[0][:50]), "12:1 is the twin of Leviticus 26:46 — the laws' frame REOPENED where the Leviticus fold closed (no cell names 26:46: the header's twin a DATA row); 11:32's 'keep to do all the statutes and the judgments which I set before you today' the tape's last Deuteronomy 11 line (blessing_and_curse_set by kind — the readback row 12:1 VERBATIM in kind); the four new lines join after it")
        dat('THE LINE demolition_restated — STATUTE by form ("these are the statutes"), at the counter\'s own day %s after blessing_and_curse_set, NO marker; the header at 12:1 declared EMPTY on the register index at the reading — REDECLARED at the compile (the class stands: the header\'s own verse at its block\'s open bound); the register\'s finder classes 12:1 a HEADER (register_probes)' % (CLOCK['counter'],))
        return out("the header's twin (12:1) — 'these are the statutes and the judgments' = Leviticus 26:46 (the fold's footer; TC by CALL), 11:32's pair (blessing_and_curse_set on the tape by kind — BC by CALL): the readback row VERBATIM in kind; THE LINE demolition_restated at the counter's day; the frame reopened", ['accepted'])
    if ask == 'the_four_nouns':
        ink('12:1', '"the statutes … the judgments … keep … to do" — the Sifrei 59:1-4 reads four nouns from the verse: exposition, law, learning and deed; "keep" and "to do" the pair %s (the book\'s seats); "which you shall keep to do" the four seats %s' % (P('תשמרון', 'לעשות'), U('תשמרון', books=('Deut',))))
        move('the Sifrei 59:1-4 (read whole at the reading)', "THE FOUR NOUNS — 'the statutes' the expositions, 'the judgments' the laws, 'keep' the learning, 'to do' the deed (59:1-4); the ladder of learning (Avot 2:1 — 79:1 at the close); 'in the land' — the land-bound rule follows (59:5)")
        dat('the four nouns a DATA row (the reading\'s find); the exam\'s person the one who learns and does not do — the learning counted apart (59:3): accepted')
        return out("the four nouns (12:1) — exposition, law, learning and deed (the Sifrei 59:1-4): 'keep' the learning, 'to do' the deed; the one who learns and does not do accepted against the deed", ['accepted'])
    if ask == 'the_land_bound_rule':
        ink('12:1', '"which you shall keep to do IN THE LAND … all the days that you live ON THE EARTH" — two scopes in one verse: "in the land" %s (the book\'s seats of the phrase counted), "on the earth" the clause %s' % (len(P('בארץ', books=('Deut',))), P('חיים', 'על', 'האדמה')))
        move('cold_run_borders (CALL) — BR.the_land_and_its_fall(the_land_bound_rule) = %s; the Sifrei 59:5; Mishnah Kiddushin 1:9 (credited — Kiddushin 36b-37a whole from 9b\'s docket)' % (BR_BOUND[0][:70],), "THE LAND-BOUND RULE — every commandment dependent on the Land applies only in the Land; those not dependent apply in the Land and outside it, except the orlah (the fruit of the first three years) and the mixed seeds (Mishnah Kiddushin 1:9): 'in the land' the obligations of the land, 'all the days … on the earth' the obligations of the body everywhere (59:5 — the borders' cell by CALL)")
        dat('the readback row 12:1\'s frame by CALL (BR.the_land_and_its_fall); the two scopes a DATA row; the exam\'s person the one who separates the tithe outside the Land — exempt by the rule, the rabbinic tithe of Babylonia the run\'s (Kiddushin 36b): accepted')
        return out("the land-bound rule (12:1) — 'in the land' the land's obligations, 'on the earth' the body's everywhere (Mishnah Kiddushin 1:9 through the Sifrei 59:5; BR.the_land_and_its_fall by CALL): the one who tithes outside the Land accepted by the rule's exception", ['accepted'])
    if ask == 'destroy_you_shall_destroy':
        ink('12:2', '"DESTROY, YOU SHALL DESTROY all the places where the nations … served their gods, on the high mountains and on the hills and UNDER EVERY LEAFY TREE" — the doubled verb in the PIEL %s against the qal at 4:26, 8:19, 30:18 %s; "under every leafy tree" the Kings\' formula %s (its Bible seats counted); the shared run with 7:5 %d (NONE in order — the demolition said in new words), with 33:52 %d' % (P('אבד', 'תאבדון'), P('אבד', 'תאבדון', books=('Deut',)) + P('אבד', 'תאבדו'), len(P('תחת', 'כל', 'עץ', 'רענן')), SH(D12(2), ('Deut', 7, 5)), SH(D12(2), ('Num', 33, 52))))
        move('cold_run_journeys (CALL) — JO.the_command(high_places) = %s; cold_run_obey_horeb (CALL) — OH.the_exile_case(perish_and_scatter) = %s; the Sifrei 60:1-4' % (JO_HIGH[0][:60], OH_PERISH[0][:40]), "dispossession_commanded (Numbers 33:50-56) on the tape by kind — 'you shall destroy all their high places' (33:52): the readback row 12:2 VARIANT; the piel of perishing where 4:26 and 8:19 have the qal (the doubled verb's kin by CALL); 'the places where the nations served' — the mountains are not their gods (Mishnah Avodah Zarah 3:5; the Sifrei 60:4); the Kings' formula (1 Kings 14:23; 2 Kings 16:4, 17:10) the run's")
        dat('the readback row 12:2 — VARIANT by kind (dispossession_commanded Num 33:50) with the verb\'s form by CALL (OH, GL); "perish, you shall perish" in the piel a DATA row; the Kings\' formula a DATA row; NO new debit (the dispossession\'s two debits and the ban\'s OPEN)')
        return out("destroy, you shall destroy (12:2) — the doubled verb in the piel (4:26's and 8:19's qal by CALL), the places on the mountains, the hills and under every leafy tree (the Kings' formula): dispossession_commanded (33:52) on the tape by kind — the readback row VARIANT; no new debit", ['accepted'])
    if ask == 'the_five_verbs':
        ink('12:3', '"you shall TEAR DOWN their altars, BREAK their pillars, BURN their Asherim with fire, CUT DOWN the images of their gods, and DESTROY their name from that place" — FIVE verbs %s where 7:5 had four and Exodus 34:13 three; "their name" the fifth object %s; the shared run with 7:5 %d, with 34:13 %d' % ([x for x, m in wm('Deut', 12, 3) if m and 'V' in m], P('ואבדתם', 'את', 'שמם'), SH(D12(3), ('Deut', 7, 5)), SH(D12(3), ('Exod', 34, 13))))
        move('cold_run_erection (CALL) — ER.covenant(demolition_grows) = %s (the verbs at Exodus 34:13, Deuteronomy 7:5 and 12:3 — the cell\'s own assert measured the chapter before its reading); cold_run_seven_nations (CALL) — SN.the_seven_nations(the_asherah_wood) = %s; cold_run_ordinances (CALL) — OR.land(break_pillars) = %s' % (ER_GROWS['v'], SN_WOOD[0][:50], OR_PILLARS['v']), "THE DEMOLITION GROWS — three at Exodus 34:13 (tear down, break, cut down), four at 7:5 (burn added), FIVE at 12:3 (the name added): the cell's own comparison [3, 4, 5]; nations_devoted (7:1-5) on the tape by kind — the ban's debit OPEN to Joshua, NO second debit; the Asherah hewn at 7:5 and BURNED at 12:3 two cases on the shelf (the wood's user flogged, Makkot 22a — SN by CALL)")
        dat('the readback row 12:3 — EXPANDED by kind (nations_devoted Deut 7:1) with the verbs by CALL (ER.covenant, SN.the_seven_nations, OR.land); the five verbs a DATA row (the_five_verbs — the counts (5, 4, 3) read from the cell); the exam\'s person the one who burns the Asherah\'s wood — flogged by the kin\'s cell: accepted')
        return out("the five verbs (12:3) — tear down, break, burn, cut down, destroy their name: five where 7:5 had four and Exodus 34:13 three (ER.covenant('demolition_grows') = [3, 4, 5] by CALL); nations_devoted on the tape by kind — the readback row EXPANDED; the Asherah burned here, hewn at 7:5 (SN by CALL)", ['accepted'])
    if ask == 'the_renaming':
        ink('12:3', '"and DESTROY THEIR NAME from that place" — the fifth verb\'s object the name; "from that place" %s (the Land the scope — 61:6); the seats of "their name" in the book %s' % (P('מן', 'המקום', 'ההוא'), [s for s in U('שמם', books=('Deut',))]))
        move('the Sifrei 61:6-7 (read whole at the reading)', "THE RENAMING FOR THE WORSE — 'destroy their name': R. Eliezer: change its name (the House of Galya, 'the revealed', called the House of Karya, 'the dungheap'; the Eye of All called the Eye of a Thorn); R. Akiva: every name given for praise renamed for shame — the dispute on the rule's reach (61:7); 'from that place' — in the Land you are commanded to pursue them, not outside the Land (61:6)")
        dat('the renaming a DATA row (R. Eliezer against R. Akiva — 61:7); the exam\'s person the one who calls the shrine by its honorific — renamed for the worse: accepted against')
        return out("the renaming (12:3) — 'destroy their name': the shrine renamed for the worse (the Sifrei 61:7 — R. Eliezer's examples, R. Akiva's rule); 'from that place' the Land the scope (61:6): the one who calls the shrine by its honorific accepted against", ['accepted'])
    if ask == 'the_mountains_not_their_gods':
        ink('12:2', '"all the places where the nations served THEIR GODS, ON THE HIGH MOUNTAINS and on the hills" — "their gods on the mountains", not "the mountains their gods": "on the high mountains" %s (the phrase\'s seats), "their gods" in the chapter %s' % (P('על', 'ההרים', 'הרמים'), [v for v in range(1, 32) for x in W12(v) if x == 'אלהיהם']))
        move('Mishnah Avodah Zarah 3:5 (the exam — credited from chapter 7\'s docket: Avodah Zarah 45a-46a); the Sifrei 60:4', "THE MOUNTAINS ARE NOT THEIR GODS — 'their gods on the mountains, but the mountains are not their gods' (Mishnah Avodah Zarah 3:5 from 12:2: the mountains and the hills themselves permitted, what is on them forbidden); R. Yosei HaGelili from 'their gods on the mountains' — why is an Asherah forbidden? because it was worked by man (45a-b); the coating on a mountain the sages' case (45b); the three Asherim (3:7) the next row")
        dat('the readback row 12:2\'s object by the answer sheet; the exam\'s person the one who worships the mountain — the mountain permitted to Israel after: accepted (Mishnah Avodah Zarah 3:5)')
        return out("the mountains not their gods (12:2) — 'their gods on the mountains', the mountains themselves permitted (Mishnah Avodah Zarah 3:5; Avodah Zarah 45a-b — credited from chapter 7's docket; the Sifrei 60:4): the one who worships the mountain accepted — the mountain not forbidden", ['accepted'])
    if ask == 'the_three_asherim':
        ink('12:3', '"and their Asherim you shall burn with fire" — the Asherim\'s seats in the book %s; "burn with fire" the seats %s' % ([s for s in U('ואשריהם', 'אשריהם', 'אשרים', 'ואשרים', 'אשרה', 'אשרת', 'ואשרת', books=('Deut',))], len(P('תשרפון', 'באש') + P('תשרפו', 'באש'))))
        move('Mishnah Avodah Zarah 3:7 (the exam — credited from chapter 7\'s docket: Avodah Zarah 48a); the Sifrei 61:5-6; cold_run_seven_nations (CALL) — SN.the_seven_nations(the_asherah_shade) = %s' % (SN_SHADE[0][:50],), "THE THREE ASHERIM — a tree planted for idolatry from the start (forbidden), a tree trimmed and shaped for idolatry (the new growth forbidden), a tree under which an idol was set (permitted when the idol is removed) — and THE THREE HOUSES — built for idolatry, plastered and adorned, an idol brought in (Mishnah Avodah Zarah 3:7 — the Sifrei 61:5-6's ladder); the shade not sat in (3:8 — SN by CALL)")
        dat('the three Asherim and the three houses the answer sheet\'s ladder on 12:3 (the Sifrei 61:5-6); the exam\'s person the one who sits in the shade of a tree an idol was set under, after its removal: accepted')
        return out("the three Asherim (12:3) — planted, shaped, an idol set under it; the three houses (Mishnah Avodah Zarah 3:7; the Sifrei 61:5-6): the one who sits in the shade of the third kind after the idol's removal accepted (SN.the_seven_nations('the_asherah_shade') by CALL)", ['accepted'])
    if ask == 'you_shall_not_do_so':
        ink('12:4', '"YOU SHALL NOT DO SO TO THE LORD YOUR GOD" — the clause the one seat in the plural %s; 12:31\'s singular pair %s; the negation %s; five tokens, the chapter\'s shortest verse' % (P('לא', 'תעשון', 'כן', 'ליהוה', 'אלהיכם'), P('לא', 'תעשה', 'כן', 'ליהוה', 'אלהיך'), [x for x in W12(4) if x in NEG]))
        move('the Sifrei 61:8 (read whole at the reading); Sanhedrin 90a:3, 113a:3, 71a:17; Avodah Zarah 13b:3; Shabbat 120b:10; Temurah 28b:7 (read whole at the docket)', "THE NAME'S ERASURE — three readings at one seat (61:8): the altar of the LORD not demolished, His Name not erased, the wrong rite not offered; THE DEMOLITION ITSELF A POSITIVE COMMAND (Sanhedrin 90a:3 — R. Yosei: even to make one letter of the Name fall is a prohibition, the demolition a command); any sacred item (Avodah Zarah 13b:3); the mezuzah's Name (Sanhedrin 113a:3, 71a:17); the act, not the cause — one may cause the erasure, not erase (Shabbat 120b:10); the coating (Temurah 28b:7); 12:31's singular pair — the wrong altar's liability keyed to the Temple's rite (81:5)")
        dat('THE WRITE name_erasure_barred — a BLOCK on israel_people at the counter\'s day (DD2, DD4): NO CELL ANYWHERE held the Name\'s erasure (the recon\'s scan; the one database on Israel %r): the code\'s hole compiled; the readback row 12:4 — SUPPLIED AS A LAW WITH THE WRITE (the first seat; 12:31 the pair)' % (PLACE_SCAN,))
        return out("you shall not do so (12:4) — the Name's erasure barred (the Sifrei 61:8's three readings; the demolition a positive command, Sanhedrin 90a:3; the act not the cause, Shabbat 120b:10): THE WRITE name_erasure_barred — a BLOCK on Israel at the chapter's own day; the readback row SUPPLIED AS A LAW with its write", ['name_erasure_barred'])
    if ask == 'the_erasures_lashes':
        ink('12:4', '"you shall not do so" — a prohibition with an act (the erasure): the lashes\' verse 25:3 "forty he shall strike him" %s' % (P('ארבעים', 'יכנו'),))
        move('Makkot 22a:9 (credited from chapter 7\'s docket — read whole there); Pesachim 48a:7 (read whole at the docket); cold_run_seven_nations (CALL) — SN.the_seven_nations(the_asherah_wood) = %s' % (SN_WOOD[1],), "THE LASHES — one who erases the Name is flogged (Makkot 22a:9's list of the flogged: the one who tears down a stone of the altar or burns the wood of the Sanctuary transgresses 'you shall not do so to the LORD your God' — Makkot 22a; Pesachim 48a:7); the Asherah's wood-burner flogged the kin (SN by CALL — Makkot 22a)")
        dat('the exam\'s person the one who erases the Name — flogged: lashes (Makkot 22a:9); the effect lashes on the court docket (the_readback\'s scene counts two lashes persons this chapter)')
        return out("the erasure's lashes (12:4) — one who erases the Name or tears down a stone of the altar is flogged (Makkot 22a:9; Pesachim 48a:7): the one who erases the Name lashed", ['lashes'])
    return out('no verdict in span', [FX.NONE])


def the_place_chosen(case, data):
    """F2 — Deut 12:5-12 — THE PLACE INSTALLED HERE (12:5 — THE LINE place_chosen_declared writing place_chosen_required and rejoicing_before_the_lord_commanded, and high_places_banned REUSED); the Name pronounced only there (Mishnah Sotah 7:6; Sotah 38a); in one of your tribes [1]; the seven offerings' lists; the rejoicing and the households (Mishnah Yoma 1:1; the woman's rejoicing Rosh Hashanah 6b); not as we do here today (Zevachim 117b); the rest and the inheritance (12:9 THE STATE ROW; Zevachim 119a-b four ways); THE STATIONS' SIX ROWS by CALL (Mishnah Zevachim 14:4-8); the three commandments of the entry (Sanhedrin 20b); the second answer sheet (Mishnah Megillah 1:10-11)"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_place_which_the_lord_will_choose':
        ink('12:5', '"BUT TO THE PLACE WHICH THE LORD YOUR GOD WILL CHOOSE from all your tribes TO PUT HIS NAME THERE — HIS DWELLING YOU SHALL SEEK, and there you shall come" — "will choose" %s (the formula\'s seats in the book: NONE BEFORE THE CHAPTER — the first %s); "to put His name there" %s and "to make His name dwell there" %s the two forms; "His dwelling" the Bible\'s one seat %s; the two seekings %s' % (len(U('יבחר', books=('Deut',))), min(U('יבחר', books=('Deut',)), key=lambda s: (int(s.split()[1].split(':')[0]), int(s.split(':')[1]))), P('לשום', 'את', 'שמו', 'שם'), P('לשכן', 'שמו', 'שם'), U('לשכנו'), P('לשכנו', 'תדרשו') + P('ובאת', 'שמה')))
        move('the tape (the recon): erected at Exod 40:17-18 (the-tabernacle — FOUND by kind and first verse; high_places_banned\'s first entry law_erection\'s write on the-land); cold_run_shemini_day (CALL) — SD.eras(ink_of_the_ban) = %s, SD.eras(switch) = %s; the Sifrei 62:1-4' % (SD_INK['v'], SD_SWITCH['v']), "THE PLACE INSTALLED HERE with no seat before it — 'will choose' none before the chapter; the erection's line the tabernacle's standing (the readback row 12:5 EXPANDED by kind); THE ERAS TABLE'S OWN INK — 'Lev 17:4 and Deut 12:8' the ban's ink by the shemini runner's own word: no new parameter, no fourth copy of the table — the chapter's law REUSES high_places_banned (a second entry on the-land's ledger at the chapter's own day, 8b's lesson) and writes place_chosen_required (a STATUS on Israel); 'His dwelling you shall seek' — seek by a prophet (62:2: 'you shall seek and come' — seek, and then the prophet tells you); Onkelos's Shekhinah")
        dat('THE LINE place_chosen_declared — STATUTE by form, at the counter\'s own day %s after demolition_restated, NO marker; THE WRITES place_chosen_required (a STATUS on israel_people) and high_places_banned (the REUSE on the-land — the second entry; the erection\'s the first: HPB_SCAN %r); the-place on the registry maps to the_place_luz_bethel (Jacob\'s — the homograph, FALSE if the census asks); THE INSTALL HYPOTHESIS on the table — 12:10-11 the ink\'s own installer, the installer boot as the form' % (CLOCK['counter'], HPB_SCAN))
        return out("the place which the LORD will choose (12:5) — installed here, no seat before it ('will choose' the book's first at 12:5; His dwelling the one seat; the two seekings): the erection's line by kind — the readback row EXPANDED; THE LINE place_chosen_declared at the counter's day writing place_chosen_required (a STATUS) and REUSING high_places_banned (the eras table's own ink — SD.eras('ink_of_the_ban') = 'Lev 17:4 and Deut 12:8' by CALL)", ['place_chosen_required'])
    if ask == 'the_name_pronounced_only_there':
        ink('12:5', '"to put His name there" — the Name\'s placing %s; "to make His name dwell there" %s; the Name in the chapter %d bare tokens; Exodus 20:20\'s "in every place where I cause My name to be mentioned" %s (the transposition\'s seat)' % (P('לשום', 'את', 'שמו', 'שם'), P('לשכן', 'שמו', 'שם'), sum(1 for v in range(1, 32) for x in W12(v) if x == 'יהוה'), P('בכל', 'המקום', 'אשר', 'אזכיר', 'את', 'שמי')))
        move('Mishnah Sotah 7:6 (at 38a:1); Sotah 38a:10, 38a:11 (read whole at the docket); cold_run_ordinances (CALL) — OR.altar(every_place) = %s' % (OR_EVERY['v'],), "THE NAME PRONOUNCED ONLY THERE — the priestly blessing: in the Temple the Name as written, in the provinces by its substitute (Mishnah Sotah 7:6); 38a:10 by the verbal analogy 'to put His name there' / 'to put My name there' (I2 — checked in MIDDOT.md); 38a:11 R. YOSHIYA'S TRANSPOSITION of Exodus 20:20 — 'in every place where I cause My name to be mentioned I will come to you' read 'in every place where I come to you — the Temple — there you may mention My name': the altar's clause (OR.altar('every_place') the hapax by CALL) read backward; Sotah 38b:10 the do-not-read reading (named, no code)")
        dat('the exam\'s person the priest who pronounces the Name as written in the provinces — accepted against (the substitute); the transposition named in MIDDOT\'s entry (no code); Onkelos 12:5 the Shekhinah supplied')
        return out("the Name pronounced only there (12:5) — the priestly blessing's Name as written in the Temple, by its substitute in the provinces (Mishnah Sotah 7:6; Sotah 38a:10 by analogy; 38a:11 R. Yoshiya's transposition of Exodus 20:20 — OR.altar('every_place') by CALL): the priest who pronounces the Name in the provinces accepted against", ['accepted'])
    if ask == 'in_one_of_your_tribes':
        ink('12:14', '"in the place which the LORD will choose IN ONE OF YOUR TRIBES" — the chapter\'s ONE number verse: the parser reads [1] %s (12:5\'s "from all your tribes" %s the plural pair); "in one of your tribes" %s' % (NUMS[14], P('מכל', 'שבטיכם'), P('באחד', 'שבטיך')))
        move('the Sifrei 62:2-3, 70:4 (read whole at the reading); Zevachim 118b:6-12 (read whole at the docket)', "'IN ONE OF YOUR TRIBES' [1] AGAINST 'FROM ALL YOUR TRIBES' — the ground from one tribe, the money from all (62:2-3; 70:4 — R. Yehuda: the money from all, the site in one); THE PORTION OF THE PLACE — Benjamin's strip (Zevachim 118b:6-12: the sanctuary in Benjamin's portion, a strip going out from Judah's — 33:12 'between his shoulders' ahead; the prophet's word the seeking)")
        dat('12:14 the chapter\'s one number verse (the parser\'s [1] measured at the reading: census_probes UNMOVED at 224 — no parser rule this sitting); the exam\'s person the tribe that claims the ground alone — the money from all: accepted against')
        return out("in one of your tribes (12:14) — [1] the chapter's one number verse against 12:5's 'from all your tribes': the ground from one tribe, the money from all (the Sifrei 62:2-3, 70:4); Benjamin's strip the portion (Zevachim 118b:6-12): the tribe that claims the ground alone accepted against", ['accepted'])
    if ask == 'the_seven_offerings':
        ink('12:6', '"your burnt offerings and your sacrifices, your tithes and the heave offering of your hand, your vows and your freewill offerings, and the firstlings of your herd and of your flock" — THE SEVEN OFFERINGS\' FIRST LIST (12:6 fourteen tokens); the second at 12:11 with "the choice of your vows" %s; the third at 12:17; "the heave offering of your hand" %s (the phrase\'s seats)' % (P('מבחר', 'נדריכם'), P('תרומת', 'ידכם') + P('תרומת', 'ידך') + P('ותרמת', 'ידכם') + P('ותרומת', 'ידך')))
