def the_burnt_offerings_only_there(case, data):
    """F3 — Deut 12:13-14 — the reuse's second entry (high_places_banned on the-land — 'take heed lest you offer your burnt offerings in every place that you see'); sanctions.outside by CALL (Leviticus 17:8-9); the prophet's exception (70:3 — Elijah on Carmel); the karet matrix (Zevachim 112b:13-15) the exam"""
    del P_[:]
    ask = case['ask']
    if ask == 'take_heed_lest_you_offer_in_every_place':
        ink('12:13', '"TAKE HEED TO YOURSELF LEST YOU OFFER YOUR BURNT OFFERINGS IN EVERY PLACE THAT YOU SEE" — "take heed … lest" the chapter\'s three (12:13, 12:19, 12:30) %s; "in every place" %s (12:13 and Numbers 18:31 — THE TWO TITHES\' twin); "your burnt offerings" in the singular half %s' % ([v for v in range(1, 32) if 'השמר' in W12(v)], P('בכל', 'מקום'), [v for v in range(1, 32) for x in W12(v) if x == 'עלתיך']))
        move('cold_run_sanctions (CALL) — SA.outside(individual) = %s, SA.outside(for_commoner) = %s; cold_run_shemini_day (CALL) — SD.eras(ink_of_the_ban) = %s; the Sifrei 70:1-2' % (SA_IND['v'], SA_COMMON['v'], SD_INK['v']), "'TAKE HEED' A PROHIBITION (70:1 — 'take heed' a negative command, 'lest' a negative command: the shelf's rule); Leviticus 17:8-9's burnt offering outside (SA.outside by CALL — the individual, not the community; the commoner's animal exempt) said again for the Land: THE REUSE — high_places_banned's SECOND ENTRY on the-land at the chapter's own day ('in every place you see barred'; the ink of the ban 'Lev 17:4 and Deut 12:8' by the shemini runner's word); Numbers 18:31's 'in every place' the Levites' tithe eaten anywhere — the same two tokens, the opposite sense (KR by CALL at F4)")
        dat('THE WRITE high_places_banned REUSED — a second entry on the-land at the counter\'s day (DD2: the erection\'s at Exod 40:17 and the chapter\'s; 8b\'s lesson: a reused effect is a second entry on the same ledger and moves an older count — THE GREP DECIDED no literal counts it ONE, Q18 and CQ5 hold booleans); the readback row 12:13 — VARIANT by CALL (SA.outside)')
        return out("take heed lest you offer in every place (12:13) — a prohibition by 'take heed … lest' (the Sifrei 70:1); Leviticus 17:8-9's outside offering said again for the Land (SA.outside by CALL — the readback row VARIANT): THE REUSE — high_places_banned's second entry on the-land at the chapter's own day (the eras table's own ink)", ['high_places_banned'])
    if ask == 'in_the_place_which_the_lord_will_choose':
        ink('12:14', '"BUT IN THE PLACE which the LORD will choose in one of your tribes, there you shall offer your burnt offerings and there you shall do ALL THAT I COMMAND YOU" — "all that I command you" singular the book\'s one %s (12:11\'s plural %s); "there … there" the two partitions %s' % (P('כל', 'אשר', 'אנכי', 'מצוך'), P('כל', 'אשר', 'אנכי', 'מצוה', 'אתכם'), [x for x in W12(14) if x in ('שם', 'ושם')]))
        move('cold_run_sanctions (CALL) — SA.platform(eras) = %s; cold_run_shemini_day (CALL) — SD.eras(table) = %s; the Sifrei 70:3-4' % ([p for _, p in SA_ERAS['v']], SD_TABLE['v']), "THE STATUS'S GROUND — 'in the place' the eras table's Jerusalem row (forbidden forever); 'all that I command you' — the burnt offerings the head, the other offerings included (70:4 — R. Yehuda: the money from all, the site in one); the two partitions 'there' and 'there' (67:4's 'there — thither'); the readback row 12:14 VERBATIM in kind by CALL (the table)")
        dat('the readback row 12:14 — VERBATIM in kind by CALL (SA.platform, SD.eras); "all that I command you" singular the book\'s one seat a DATA row; the exam\'s person the one who offers outside after Shiloh\'s standing — the karet matrix (the next row): accepted against')
        return out("in the place which the LORD will choose (12:14) — the eras table's Jerusalem row, the burnt offerings the head and all that I command you (the Sifrei 70:4): SD.eras('table') and SA.platform('eras') by CALL — the readback row VERBATIM in kind; the one who offers outside after Shiloh accepted against", ['accepted'])
    if ask == 'the_prophets_exception':
        ink('12:13', '"lest you offer your burnt offerings in every place that you see" — "THAT YOU SEE" the clause %s: not in every place you see, but in the place a prophet tells you' % (P('אשר', 'תראה'),))
        move('the Sifrei 70:3 (read whole at the reading); Zevachim 119b:8 (the do-not-read reading named at the docket)', "THE PROPHET'S EXCEPTION — 'in every place that you see' you may not offer, but you may offer by the word of a prophet: ELIJAH ON MOUNT CARMEL (1 Kings 18 — the Sifrei 70:3; the run's case outside the tape); the prophet's word the exception's channel, the shelf's rule not the ink's")
        dat('the prophet\'s exception a DATA row (the design predicted it); the exam\'s person Elijah on Carmel — EXEMPT from the outside-offering ban by the prophet\'s word (70:3)')
        return out("the prophet's exception (12:13) — 'in every place that you see' you may not, but by a prophet's word you may: Elijah on Carmel exempt (the Sifrei 70:3)", ['exempt'])
    if ask == 'the_karet_matrix':
        ink('12:13-14', '"lest you offer … in every place … but in the place" — the eras\' flips and the karet (excision) for the offering outside during a forbidden era; "offer" (the hiphil of ascending) %s' % ([x for x, m in wm('Deut', 12, 13) if m and 'Vh' in m],))
        move('cold_run_shemini_day (CALL) — SD.eras(karet_matrix) = %s, SD.eras(differences) = %s; cold_run_sanctions (CALL) — SA.platform(no_karet_for_platform) = %s, SA.platform(differences) = %s; Zevachim 112b:13-15, 119b:10-12, 112b:16-113a:2 (read whole at the docket)' % (SD_MATRIX['v'], SD_DIFF['v'], SA_NOKARET['v'], len(SA_DIFF['v'])), "THE KARET MATRIX — during the Tabernacle's and Jerusalem's eras the offering outside a positive command, a prohibition and karet; during Shiloh's a positive command and a prohibition (no karet — Zevachim 112b:13-15; R. Shimon's four principles 119b:10-12); THE ELEVEN DIFFERENCES between the great altar and the private altar (112b:16-113a:2; 119b:13-20 — the laying on, the north, the blood around, the waving, the presenting, the priesthood, the garments, the vessels, the aroma, the partition, the sun's setting: the private altar's offense carries no karet of its own, SA.platform by CALL)")
        dat('the karet matrix and the eleven differences the exam\'s rows by CALL (the table\'s cells, unmoved); the exam\'s person the one who offers outside after Shiloh\'s standing — a positive command and a prohibition, no karet (Shiloh\'s era): accepted (112b:14)')
        return out("the karet matrix (12:13-14) — karet for the offering outside under the Tabernacle and Jerusalem, none under Shiloh (Zevachim 112b:13-15 — SD.eras('karet_matrix') by CALL); the eleven differences (SD.eras('differences') = 11; SA.platform by CALL): the one who offers outside after Shiloh's standing accepted — no karet in Shiloh's era", ['accepted'])
    return out('no verdict in span', [FX.NONE])
